using UAF.Domain.Entities;
namespace UAF.Application.Features.Workflows;
public sealed record ApprovalStageRequest(string RequiredRole,Guid? AssignedUserId);
public sealed record StartWorkflowRequest(string ResourceType,Guid ResourceId,IReadOnlyList<ApprovalStageRequest> Stages,string? Comments);
public sealed record WorkflowDecisionRequest(string? Comments);
public interface IWorkflowRepository{Task<bool> HasActiveAsync(string type,Guid resource,CancellationToken ct);Task AddAsync(WorkflowInstance workflow,IReadOnlyList<WorkflowApprovalStep> steps,WorkflowHistory history,CancellationToken ct);Task<(WorkflowInstance Workflow,WorkflowApprovalStep Step)?> GetCurrentAsync(Guid id,CancellationToken ct);Task AddHistoryAsync(WorkflowHistory history,CancellationToken ct);Task SaveChangesAsync(CancellationToken ct);Task<IReadOnlyList<WorkflowHistory>> HistoryAsync(Guid id,CancellationToken ct);}
public sealed class ApprovalWorkflowService{
 private readonly IWorkflowRepository _repo;public ApprovalWorkflowService(IWorkflowRepository repo)=>_repo=repo;
 public async Task<Guid> StartAsync(StartWorkflowRequest r,Guid actor,CancellationToken ct){if(r.Stages is null||r.Stages.Count is <1 or >10)throw new ArgumentException("Provide 1 to 10 approval stages.");if(actor==Guid.Empty)throw new ArgumentException("Requester required.");if(await _repo.HasActiveAsync(r.ResourceType,r.ResourceId,ct))throw new InvalidOperationException("An active workflow already exists for this resource.");var w=new WorkflowInstance(r.ResourceType,r.ResourceId,actor,r.Stages.Count);var steps=r.Stages.Select((s,i)=>new WorkflowApprovalStep(w.Id,i+1,s.RequiredRole,s.AssignedUserId)).ToArray();await _repo.AddAsync(w,steps,new WorkflowHistory(w.Id,r.ResourceType,r.ResourceId,actor,"None","Pending",r.Comments,DateTimeOffset.UtcNow),ct);return w.Id;}
 public async Task DecideAsync(Guid id,Guid actor,IEnumerable<string> roles,bool approve,string? comments,CancellationToken ct){var current=await _repo.GetCurrentAsync(id,ct)??throw new KeyNotFoundException("Workflow not found.");var(w,step)=current;var role=roles.FirstOrDefault(candidate=>string.Equals(candidate,step.RequiredRole,StringComparison.OrdinalIgnoreCase));if(string.IsNullOrWhiteSpace(role))throw new UnauthorizedAccessException("Role cannot approve this stage.");var old=w.Status.ToString();step.Decide(actor,role,approve,comments,DateTimeOffset.UtcNow);if(approve)w.Advance(DateTimeOffset.UtcNow);else w.Reject(DateTimeOffset.UtcNow);var next=w.Status==UAF.Domain.Enums.WorkflowStatus.Pending?$"PendingStage{w.CurrentStage}":w.Status.ToString();await _repo.AddHistoryAsync(new WorkflowHistory(w.Id,w.ResourceType,w.ResourceId,actor,old,next,comments,DateTimeOffset.UtcNow),ct);await _repo.SaveChangesAsync(ct);}
 public Task<IReadOnlyList<WorkflowHistory>> HistoryAsync(Guid id,CancellationToken ct)=>_repo.HistoryAsync(id,ct);
}
